package cn.wenjin.admission.workflow;

import cn.wenjin.admission.common.Ids;
import cn.wenjin.admission.common.Jsons;
import cn.wenjin.admission.domain.Domain.AdvisorRunState;
import cn.wenjin.admission.domain.Domain.Report;
import cn.wenjin.admission.domain.Domain.RunStatus;
import cn.wenjin.admission.domain.Domain.ScoredCandidate;
import cn.wenjin.admission.domain.Domain.RiskItem;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Repository
public class RunRepository {
    private final JdbcClient jdbc;
    public RunRepository(JdbcClient jdbc){this.jdbc=jdbc;}

    public String create(String runId,String conversationId,String userId,String profileId,String key,String profileJson){
        Optional<String> existing=jdbc.sql("select id from advisor_runs where idempotency_key=:key and status in ('QUEUED','RUNNING','WAITING_FOR_PROFILE','COMPLETED','DEGRADED')").param("key",key).query(String.class).optional();
        if(existing.isPresent())return existing.get();Instant now=Instant.now();
        existing=jdbc.sql("select id from advisor_runs where conversation_id=:conversationId and user_id=:userId and status in ('QUEUED','RUNNING') order by created_at desc fetch first 1 row only")
                .param("conversationId",conversationId).param("userId",userId).query(String.class).optional();
        if(existing.isPresent())return existing.get();
        jdbc.sql("insert into advisor_runs(id,conversation_id,user_id,profile_id,idempotency_key,status,current_node,profile_snapshot_json,created_at,updated_at) values (:id,:conversationId,:userId,:profileId,:key,'QUEUED','queued',:profile,:now,:now)").param("id",runId).param("conversationId",conversationId).param("userId",userId).param("profileId",profileId).param("key",key).param("profile",profileJson).param("now",java.sql.Timestamp.from(now)).update();return runId;
    }
        public void checkpoint(AdvisorRunState s){Instant now=Instant.now();java.sql.Timestamp sqlNow=java.sql.Timestamp.from(now);int seq=jdbc.sql("select count(*) from advisor_run_checkpoints where run_id=:id").param("id",s.runId()).query(Integer.class).single()+1;String json=Jsons.write(s);jdbc.sql("insert into advisor_run_checkpoints(id,run_id,node_name,sequence_no,state_json,created_at) values (:id,:runId,:node,:seq,:state,:now)").param("id",Ids.uuid()).param("runId",s.runId()).param("node",s.currentNode()).param("seq",seq).param("state",json).param("now",sqlNow).update();jdbc.sql("update advisor_runs set status=:status,current_node=:node,dataset_version=:dataset,state_json=:state,error_message=:error,started_at=coalesce(started_at,:now),completed_at=:completed,updated_at=:now where id=:id").param("status",s.status().name()).param("node",s.currentNode()).param("dataset",s.datasetVersion()).param("state",json).param("error",s.errorMessage()).param("completed",List.of(RunStatus.COMPLETED,RunStatus.DEGRADED,RunStatus.FAILED,RunStatus.CANCELLED).contains(s.status())?sqlNow:null).param("now",sqlNow).param("id",s.runId()).update();}
    public Optional<AdvisorRunState> state(String id,String userId){return jdbc.sql("select state_json from advisor_runs where id=:id and user_id=:userId").param("id",id).param("userId",userId).query(String.class).optional().filter(x->!x.isBlank()).map(x->Jsons.read(x,AdvisorRunState.class));}
    public RunView view(String id,String userId){return jdbc.sql("select id,conversation_id,status,current_node,dataset_version,error_message,created_at,updated_at from advisor_runs where id=:id and user_id=:userId").param("id",id).param("userId",userId).query((rs,n)->new RunView(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getTimestamp(7).toInstant(),rs.getTimestamp(8).toInstant())).optional().orElseThrow(()->new IllegalArgumentException("任务不存在"));}
    public void requestCancel(String id,String userId){view(id,userId);jdbc.sql("update advisor_runs set cancel_requested=true,updated_at=:now where id=:id").param("id",id).param("now",java.sql.Timestamp.from(Instant.now())).update();}
    public boolean cancelRequested(String id){return jdbc.sql("select cancel_requested from advisor_runs where id=:id").param("id",id).query(Boolean.class).single();}
    public String saveReport(Report report,String userId,String recommendationId){Optional<String> existing=jdbc.sql("select id from reports where run_id=:runId and version=:version").param("runId",report.runId()).param("version",report.version()).query(String.class).optional();if(existing.isPresent())return existing.get();java.sql.Timestamp sqlNow=java.sql.Timestamp.from(Instant.now());jdbc.sql("insert into reports(id,run_id,user_id,recommendation_id,version,status,title,report_json,dataset_version,compliance_passed,compliance_issues_json,reflection_iterations,created_at,updated_at) values (:id,:runId,:userId,:recommendationId,:version,'COMPLETED',:title,:json,:dataset,:passed,:issues,:iterations,:now,:now)").param("id",report.id()).param("runId",report.runId()).param("userId",userId).param("recommendationId",recommendationId).param("version",report.version()).param("title",report.title()).param("json",Jsons.write(report)).param("dataset",report.datasetVersion()).param("passed",report.compliancePassed()).param("issues",Jsons.write(report.complianceIssues())).param("iterations",report.reflectionIterations()).param("now",sqlNow).update();return report.id();}
    public String saveRecommendation(String runId,String profileId,String dataset,List<ScoredCandidate> items,List<RiskItem> risks){Optional<String> existing=jdbc.sql("select id from recommendation_results where run_id=:runId").param("runId",runId).query(String.class).optional();if(existing.isPresent())return existing.get();String id=Ids.uuid();java.sql.Timestamp sqlNow=java.sql.Timestamp.from(Instant.now());jdbc.sql("insert into recommendation_results(id,run_id,profile_id,dataset_version,strategy,summary_json,created_at) values (:id,:runId,:profileId,:dataset,'BALANCED',:summary,:now)").param("id",id).param("runId",runId).param("profileId",profileId).param("dataset",dataset).param("summary",Jsons.write(Map.of("candidateCount",items.size()))).param("now",sqlNow).update();int order=0;for(ScoredCandidate item:items){String itemId=Ids.uuid();jdbc.sql("insert into recommendation_items(id,recommendation_id,admission_record_id,tier,total_score,score_breakdown_json,reasons_json,evidence_ids_json,rule_result_ids_json,source_ids_json,sort_order) values (:id,:recommendationId,:recordId,:tier,:score,:breakdown,:reasons,:evidence,:rules,:sources,:sort)").param("id",itemId).param("recommendationId",id).param("recordId",item.record().id()).param("tier",item.tier()).param("score",item.totalScore()).param("breakdown",Jsons.write(item.scoreBreakdown())).param("reasons",Jsons.write(item.reasons())).param("evidence",Jsons.write(item.evidenceIds())).param("rules",Jsons.write(item.ruleResultIds())).param("sources",Jsons.write(item.sourceIds())).param("sort",order++).update();}for(RiskItem risk:risks){jdbc.sql("insert into risk_items(id,run_id,recommendation_item_id,risk_code,level,title,detail,evidence_ids_json,blocking) values (:id,:runId,null,:code,:level,:title,:detail,:evidence,:blocking)").param("id",risk.id()).param("runId",runId).param("code",risk.code()).param("level",risk.level().name()).param("title",risk.title()).param("detail",risk.detail()).param("evidence",Jsons.write(risk.evidenceIds())).param("blocking",risk.blocking()).update();}return id;}
    public List<RecoverableRun> recoverableRuns(){return jdbc.sql("select id,conversation_id,user_id,coalesce(state_json,profile_snapshot_json) from advisor_runs where status in ('QUEUED','RUNNING') and cancel_requested=false order by created_at").query((rs,n)->new RecoverableRun(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4))).list();}
    public Optional<RecoverableRun> recoverableRun(String id){return jdbc.sql("select id,conversation_id,user_id,coalesce(state_json,profile_snapshot_json) from advisor_runs where id=:id and status in ('QUEUED','RUNNING') and cancel_requested=false").param("id",id).query((rs,n)->new RecoverableRun(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4))).optional();}
    public Optional<Report> report(String id,String userId){return jdbc.sql("select report_json from reports where id=:id and user_id=:userId and deleted_at is null").param("id",id).param("userId",userId).query(String.class).optional().map(x->Jsons.read(x,Report.class));}
    public Optional<Report> reportByRun(String runId,String userId){return jdbc.sql("select report_json from reports where run_id=:runId and user_id=:userId and deleted_at is null order by version desc fetch first 1 row only").param("runId",runId).param("userId",userId).query(String.class).optional().map(x->Jsons.read(x,Report.class));}
    public List<ReportSummary> reports(String userId){return jdbc.sql("select id,run_id,version,title,dataset_version,compliance_passed,created_at from reports where user_id=:userId and deleted_at is null order by created_at desc").param("userId",userId).query((rs,n)->new ReportSummary(rs.getString(1),rs.getString(2),rs.getInt(3),rs.getString(4),rs.getString(5),rs.getBoolean(6),rs.getTimestamp(7).toInstant())).list();}
    public record RunView(String id,String conversationId,String status,String currentNode,String datasetVersion,String errorMessage,Instant createdAt,Instant updatedAt){}
    public record ReportSummary(String id,String runId,int version,String title,String datasetVersion,boolean compliancePassed,Instant createdAt){}
    public record RecoverableRun(String id,String conversationId,String userId,String stateOrProfileJson){}
}
